using System.Collections.Generic;
using UnityEngine;

namespace Undercurrent.Runtime.Presentation
{
    /// <summary>
    /// Creates runtime materials and sprites. Base materials are loaded from Resources (generated by the
    /// "Undercurrent/Setup Project" editor command) so that their shaders are guaranteed to be included in
    /// player builds; Shader.Find is only a fallback for the Editor.
    /// </summary>
    public static class VisualAssets
    {
        private static Material _litBase;
        private static Material _unlitBase;
        private static Material _particleBase;
        private static readonly Dictionary<int, Material> LitCache = new Dictionary<int, Material>();
        private static Sprite _rounded;
        private static Sprite _circle;
        private static Sprite _white;
        private static Font _font;

        public static Font Font
        {
            get
            {
                if (_font == null) _font = Resources.GetBuiltinResource<Font>("LegacyRuntime.ttf");
                return _font;
            }
        }

        private static Material LoadBase(ref Material cache, string resourcePath, params string[] shaderNames)
        {
            if (cache != null) return cache;
            var asset = Resources.Load<Material>(resourcePath);
            // Work on a copy: editing the Resources asset in Play Mode would modify the project file.
            cache = asset != null ? new Material(asset) : null;
            if (cache == null)
            {
                foreach (var name in shaderNames)
                {
                    var shader = Shader.Find(name);
                    if (shader == null) continue;
                    cache = new Material(shader);
                    break;
                }
                if (cache == null)
                {
                    Debug.LogError($"[Undercurrent] No shader available for {resourcePath}. Run 'Undercurrent/Setup Project' in the Editor.");
                    cache = new Material(Shader.Find("Hidden/InternalErrorShader"));
                }
            }
            return cache;
        }

        public static Material LitBase => LoadBase(ref _litBase, "Undercurrent/Materials/BaseLit",
            "Universal Render Pipeline/Lit", "Standard");

        public static Material UnlitBase => LoadBase(ref _unlitBase, "Undercurrent/Materials/BaseUnlit",
            "Universal Render Pipeline/Unlit", "Unlit/Color");

        public static Material ParticleBase
        {
            get
            {
                if (_particleBase != null) return _particleBase;
                var m = LoadBase(ref _particleBase, "Undercurrent/Materials/BaseParticle",
                    "Universal Render Pipeline/Particles/Unlit", "Particles/Standard Unlit", "Sprites/Default");
                var dot = SoftDot();
                if (m.HasProperty("_BaseMap")) m.SetTexture("_BaseMap", dot);
                if (m.HasProperty("_MainTex")) m.SetTexture("_MainTex", dot);
                return m;
            }
        }

        private static Texture2D SoftDot()
        {
            const int size = 32;
            var tex = new Texture2D(size, size, TextureFormat.RGBA32, false) { name = "UC_SoftDot", wrapMode = TextureWrapMode.Clamp };
            var px = new Color32[size * size];
            for (int y = 0; y < size; y++)
            for (int x = 0; x < size; x++)
            {
                float dx = (x + 0.5f) / size * 2f - 1f, dy = (y + 0.5f) / size * 2f - 1f;
                float a = Mathf.Clamp01(1f - Mathf.Sqrt(dx * dx + dy * dy));
                px[y * size + x] = new Color32(255, 255, 255, (byte)(a * a * 255f));
            }
            tex.SetPixels32(px);
            tex.Apply();
            return tex;
        }

        /// <summary>Shared lit material for a colour/smoothness pair (cached so draw calls can batch).</summary>
        public static Material Lit(Color color, float smoothness = 0.35f, float metallic = 0f)
        {
            int key = ((Color32)color).GetHashCode() ^ (int)(smoothness * 1000f) * 397 ^ (int)(metallic * 1000f) * 7919;
            if (LitCache.TryGetValue(key, out var m) && m != null) return m;
            m = new Material(LitBase) { name = "UC_Lit_" + ColorUtility.ToHtmlStringRGB(color) };
            SetColor(m, color);
            if (m.HasProperty("_Smoothness")) m.SetFloat("_Smoothness", smoothness);
            if (m.HasProperty("_Glossiness")) m.SetFloat("_Glossiness", smoothness);
            if (m.HasProperty("_Metallic")) m.SetFloat("_Metallic", metallic);
            // Emission enabled (black) so hit flashes can drive _EmissionColor through property blocks.
            SetEmission(m, Color.black);
            LitCache[key] = m;
            return m;
        }

        public static Material Unlit(Color color)
        {
            var m = new Material(UnlitBase);
            SetColor(m, color);
            return m;
        }

        public static void SetColor(Material m, Color color)
        {
            if (m.HasProperty("_BaseColor")) m.SetColor("_BaseColor", color);
            if (m.HasProperty("_Color")) m.SetColor("_Color", color);
        }

        public static void SetEmission(Material m, Color emission)
        {
            if (!m.HasProperty("_EmissionColor")) return;
            m.EnableKeyword("_EMISSION");
            m.SetColor("_EmissionColor", emission);
        }

        public static Color Hex(string rrggbb, float alpha = 1f)
        {
            if (!string.IsNullOrEmpty(rrggbb) && ColorUtility.TryParseHtmlString("#" + rrggbb, out var c))
            {
                c.a = alpha;
                return c;
            }
            return new Color(1f, 0f, 1f, alpha);
        }

        // ------------------------------------------------------------------ UI sprites

        public static Sprite White
        {
            get
            {
                if (_white == null)
                {
                    var tex = new Texture2D(4, 4, TextureFormat.RGBA32, false) { name = "UC_White" };
                    var px = new Color32[16];
                    for (int i = 0; i < px.Length; i++) px[i] = new Color32(255, 255, 255, 255);
                    tex.SetPixels32(px);
                    tex.Apply();
                    _white = Sprite.Create(tex, new Rect(0, 0, 4, 4), new Vector2(0.5f, 0.5f), 100f);
                }
                return _white;
            }
        }

        /// <summary>9-sliced rounded rectangle, generated once with anti-aliased corners.</summary>
        public static Sprite Rounded
        {
            get
            {
                if (_rounded == null) _rounded = BuildRounded(64, 18);
                return _rounded;
            }
        }

        public static Sprite Circle
        {
            get
            {
                if (_circle == null) _circle = BuildRounded(128, 64, sliced: false);
                return _circle;
            }
        }

        private static Sprite BuildRounded(int size, int radius, bool sliced = true)
        {
            var tex = new Texture2D(size, size, TextureFormat.RGBA32, false) { name = "UC_Rounded", wrapMode = TextureWrapMode.Clamp };
            var px = new Color32[size * size];
            for (int y = 0; y < size; y++)
            {
                for (int x = 0; x < size; x++)
                {
                    float cx = Mathf.Clamp(x + 0.5f, radius, size - radius);
                    float cy = Mathf.Clamp(y + 0.5f, radius, size - radius);
                    float d = Vector2.Distance(new Vector2(x + 0.5f, y + 0.5f), new Vector2(cx, cy));
                    float a = Mathf.Clamp01(radius - d + 0.5f);
                    px[y * size + x] = new Color32(255, 255, 255, (byte)(a * 255f));
                }
            }
            tex.SetPixels32(px);
            tex.Apply();
            var border = sliced ? new Vector4(radius, radius, radius, radius) : Vector4.zero;
            return Sprite.Create(tex, new Rect(0, 0, size, size), new Vector2(0.5f, 0.5f), 100f, 0, SpriteMeshType.FullRect, border);
        }
    }
}
